// title.post.ts — auto-generates a short title for a chat after the first message
//
// Called by useChat.generateChatTitle() right after the user sends their first
// message. Uses the same provider/model/token that the user has configured in
// Settings, so the title is generated by the same model they are chatting with.
//
// Flow:
//   useChat.sendMessage() (first message)
//     → POST /api/chats/[id]/title { message, provider, model, x-ai-token }
//       → createModel(provider, model, apiKey)
//       → generateChatTitle() asks the model for a 3-word summary
//       → updateChat() persists the title to the DB
//       → returns the updated Chat so the sidebar updates immediately

import { generateChatTitle, createModel } from '../../../services/ai-service';
import { updateChat } from '../../../repository/chatRepository';
import { UpdateChatTitleSchema } from '../../../schema';

export default defineEventHandler(async e => {
  const { id } = getRouterParams(e);

  const { success, data } = await readValidatedBody(
    e,
    UpdateChatTitleSchema.safeParse
  );

  if (!success) {
    throw createError({ statusCode: 400, statusMessage: 'Bad Request' });
  }

  // Resolve provider/model/token using the same priority as the stream endpoint:
  // 1. x-ai-token header (UI-configured key, sent by useChat)
  // 2. body.apiToken (fallback if header is not used)
  // 3. Server-side env var NUXT_OPENAI_API_KEY (shared fallback for OpenAI)
  const provider: string = data.provider ?? 'openai';
  const modelName: string = data.model ?? 'gpt-6-luna';
  const apiKey: string =
    getHeader(e, 'x-ai-token') || useRuntimeConfig().openaiApiKey || '';

  const model = createModel(provider, modelName, apiKey);
  const title = await generateChatTitle(model, data.message);

  return updateChat(id as string, { title });
});
